package org.retrobridge.galaxyservices.s2;
import android.app.*;import android.content.*;import android.os.*;import android.speech.*;import android.widget.*;import java.util.*;

/** Legacy intent interface for Maps, YouTube and other apps' microphone buttons. */
public final class SpeechActivity extends Activity implements RecognitionListener {
 SpeechRecognizer recognizer;TextView status;Button done;boolean completed;
 public void onCreate(Bundle b){super.onCreate(b);setTitle("Voice input");LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,20,24,16);ImageView mic=new ImageView(this);mic.setImageResource(android.R.drawable.ic_btn_speak_now);l.addView(mic,new LinearLayout.LayoutParams(-1,70));status=new TextView(this);status.setGravity(17);status.setTextSize(20);status.setText("Speak now");l.addView(status,new LinearLayout.LayoutParams(-1,65));done=new Button(this);done.setText("Done");done.setOnClickListener(v->{done.setEnabled(false);status.setText("Working…");recognizer.stopListening();});l.addView(done);Button cancel=new Button(this);cancel.setText("Cancel");cancel.setOnClickListener(v->finish());l.addView(cancel);setContentView(l);recognizer=SpeechRecognizer.createSpeechRecognizer(this,new ComponentName(this,PixelRecognitionService.class));recognizer.setRecognitionListener(this);Intent i=new Intent(getIntent());i.setAction(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);recognizer.startListening(i);}
 public void onResults(Bundle b){if(completed)return;completed=true;ArrayList<String> words=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);Intent result=new Intent().putStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS,words);PendingIntent target=getIntent().getParcelableExtra(RecognizerIntent.EXTRA_RESULTS_PENDINGINTENT);if(target!=null){Bundle extra=getIntent().getBundleExtra(RecognizerIntent.EXTRA_RESULTS_PENDINGINTENT_BUNDLE);if(extra!=null)result.putExtras(extra);if(words!=null&&!words.isEmpty())result.putExtra(android.app.SearchManager.QUERY,words.get(0));try{target.send(this,RESULT_OK,result);}catch(PendingIntent.CanceledException ignored){}}else if(RecognizerIntent.ACTION_WEB_SEARCH.equals(getIntent().getAction())&&getCallingActivity()==null&&words!=null&&!words.isEmpty()){Intent search=new Intent(Intent.ACTION_WEB_SEARCH).putExtra(android.app.SearchManager.QUERY,words.get(0));try{startActivity(search);}catch(Exception ignored){}}setResult(RESULT_OK,result);finish();}
 public void onError(int e){status.setText(e==SpeechRecognizer.ERROR_NO_MATCH||e==SpeechRecognizer.ERROR_SPEECH_TIMEOUT?"Didn't catch that":e==SpeechRecognizer.ERROR_RECOGNIZER_BUSY?"Voice input is busy":"Couldn't reach Pixel");done.setEnabled(true);done.setText("Try again");done.setOnClickListener(v->{done.setText("Done");done.setOnClickListener(w->{done.setEnabled(false);status.setText("Working…");recognizer.stopListening();});Intent i=new Intent(getIntent());i.setAction(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);recognizer.startListening(i);});}
 public void onReadyForSpeech(Bundle b){status.setText("Speak now");}public void onBeginningOfSpeech(){status.setText("Listening…");}public void onEndOfSpeech(){status.setText("Working…");done.setEnabled(false);}public void onRmsChanged(float r){}public void onBufferReceived(byte[] b){}public void onPartialResults(Bundle b){}public void onEvent(int t,Bundle b){}public void onDestroy(){if(recognizer!=null)recognizer.destroy();super.onDestroy();}
}
